  // â”€â”€ Hairstyles per class â€” generated from CLASS_HAIR_FAMILIES â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  // IDs are hair1â€¦hairN scoped by classId (app.jsx filters by classId).
  // maleAppearanceId/femaleAppearanceId are null when that gender has fewer
  // styles than the other (e.g. roublard male stops at 7, female goes to 8).
  const HAIRSTYLES = Object.entries(CLASS_HAIR_FAMILIES).flatMap(([classId, family]) => {
    const maxStyles = Math.max(family.maleCount, family.femaleCount);
    return Array.from({ length: maxStyles }, (_, i) => ({
      id: `hair${i + 1}`,
      label: `Estilo ${i + 1}`,
      classId,
      maleAppearanceId:   i < family.maleCount   ? `${family.malePrefix}${String(i + 1).padStart(3, '0')}`   : null,
      femaleAppearanceId: i < family.femaleCount  ? `${family.femalePrefix}${String(i + 1).padStart(3, '0')}` : null,
    }));
  });

  // Legacy alias so any existing reference to HAIR_STYLES doesn't break
  const HAIR_STYLES = HAIRSTYLES;

